import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { SelectOption } from "./Select";

type Props = {
  value: string;
  onChange: (value: string) => void;
  options: SelectOption[];
  className?: string;
  title?: string;
};

/** Lucide activity */
function ActivityIcon({ size = 14 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M22 12h-2.48a2 2 0 0 0-1.93 1.46l-2.35 8.36a.25.25 0 0 1-.48 0L9.24 2.18a.25.25 0 0 0-.48 0l-2.35 8.36A2 2 0 0 1 4.49 12H2" />
    </svg>
  );
}

export function ActionMenu({
  value,
  onChange,
  options,
  className,
  title = "Actions",
}: Props) {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState({ top: 0, left: 0 });
  const rootRef = useRef<HTMLDivElement>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const active = Boolean(value);
  const current =
    options.find((o) => o.value === value)?.label ??
    (value ? value : "all actions");

  const place = () => {
    const el = btnRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    let left = r.left;
    const width = 180;
    if (left + width > window.innerWidth - 8) {
      left = Math.max(8, window.innerWidth - width - 8);
    }
    setPos({ top: r.bottom + 4, left });
  };

  useEffect(() => {
    if (!open) return;
    place();
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        const menus = document.querySelectorAll(".action-menu-dropdown");
        for (const m of menus) if (m.contains(e.target as Node)) return;
        setOpen(false);
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    const onScroll = () => place();
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    window.addEventListener("resize", onScroll);
    window.addEventListener("scroll", onScroll, true);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("resize", onScroll);
      window.removeEventListener("scroll", onScroll, true);
    };
  }, [open]);

  return (
    <div
      className={`action-menu${className ? ` ${className}` : ""}`}
      ref={rootRef}
    >
      <button
        type="button"
        ref={btnRef}
        className={`btn-icon action-menu-trigger${open ? " open" : ""}${active ? " active" : ""}`}
        aria-expanded={open}
        aria-haspopup="menu"
        aria-label={`${title}: ${current}`}
        title={`${title}: ${current}`}
        onClick={() => setOpen((o) => !o)}
      >
        <ActivityIcon />
      </button>
      {open &&
        createPortal(
          <div
            className="action-menu-dropdown hppm-select-menu-portal"
            role="menu"
            style={{ top: pos.top, left: pos.left, minWidth: 168 }}
          >
            {options.map((o) => (
              <button
                key={o.value || "__all__"}
                type="button"
                role="menuitemradio"
                aria-checked={value === o.value}
                className={value === o.value ? "selected" : ""}
                onClick={() => {
                  onChange(o.value);
                  setOpen(false);
                }}
              >
                {o.label}
              </button>
            ))}
          </div>,
          document.body
        )}
    </div>
  );
}

import type { IncomingMessage, ServerResponse } from "node:http";
import {
  parseAllTasks,
  moveTask,
  moveTaskToFile,
  toggleTask,
  getOverview,
  createTask,
  createArea,
  checkAreaName,
  renameArea,
  updateTaskText,
  deleteTask,
} from "./markdown";
import {
  updateTaskMeta,
  addGlobalTag,
  loadStore,
  describeMetaChange,
  getTagStyles,
  setTagStyle,
  renameGlobalTag,
  deleteGlobalTag,
  tagPalette,
  listAllTags,
  getTrackerStyles,
  setTrackerStyle,
} from "./store";
import { getAnalyticsData } from "./analytics";
import { appendAudit, listAudit, clearAudit } from "./audit";
import {
  listProjects,
  getActiveProject,
  getActiveRoot,
  openProject,
  closeProject,
  createProject,
  checkProjectPath,
  suggestPaths,
  browseDirs,
  getDefaultRoot,
  inspectProjectDir,
  createBrowseFolder,
  getWorkspaceRoot,
  setWorkspaceRoot,
  rescanWorkspace,
} from "./projects";
import { loadPreferences, savePreferences } from "./preferences";

function requireRoot(): string {
  return getActiveRoot();
}

export function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk: Buffer) => (data += chunk.toString()));
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

/**
 * Shared /api middleware for Vite dev and the desktop standalone server.
 * Returns true if the request was handled.
 */
export async function handleHppmApi(
  req: IncomingMessage,
  res: ServerResponse
): Promise<boolean> {
  if (!req.url?.startsWith("/api/")) return false;

  res.setHeader("Content-Type", "application/json");

  try {
    // —— Projects (no active root required) ——
    if (req.url === "/api/projects" && req.method === "GET") {
      res.end(
        JSON.stringify({
          projects: listProjects(),
          active: getActiveProject(),
          workspaceRoot: getWorkspaceRoot(),
        })
      );
      return true;
    }

    if (req.url === "/api/projects/active" && req.method === "GET") {
      res.end(JSON.stringify({ active: getActiveProject() }));
      return true;
    }

    if (req.url === "/api/projects/workspace" && req.method === "GET") {
      res.end(
        JSON.stringify({
          workspaceRoot: getWorkspaceRoot(),
          projects: listProjects(),
        })
      );
      return true;
    }

    if (req.url === "/api/projects/workspace" && req.method === "PUT") {
      const body = await readBody(req);
      const data = JSON.parse(body || "{}") as { root?: string | null };
      const result = setWorkspaceRoot(
        data.root === undefined ? null : data.root
      );
      res.end(JSON.stringify({ ok: true, ...result }));
      return true;
    }

    if (req.url === "/api/projects/workspace/rescan" && req.method === "POST") {
      const result = rescanWorkspace();
      res.end(JSON.stringify({ ok: true, ...result }));
      return true;
    }

    if (req.url === "/api/projects/open" && req.method === "POST") {
      const body = await readBody(req);
      const { id } = JSON.parse(body);
      const project = openProject(id);
      res.end(JSON.stringify({ ok: true, project }));
      return true;
    }

    if (req.url === "/api/projects/close" && req.method === "POST") {
      closeProject();
      res.end(JSON.stringify({ ok: true }));
      return true;
    }

    if (req.url === "/api/projects/create" && req.method === "POST") {
      const body = await readBody(req);
      const data = JSON.parse(body);
      const project = createProject(data);
      res.end(JSON.stringify({ ok: true, project }));
      return true;
    }

    if (req.url?.startsWith("/api/projects/check") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const dir = u.searchParams.get("dir") ?? "";
      res.end(JSON.stringify(checkProjectPath(dir)));
      return true;
    }

    if (req.url?.startsWith("/api/projects/suggest") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const q = u.searchParams.get("q") ?? "";
      res.end(JSON.stringify({ paths: suggestPaths(q) }));
      return true;
    }

    if (req.url?.startsWith("/api/projects/browse") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const dir = u.searchParams.get("dir") ?? "";
      res.end(JSON.stringify(browseDirs(dir || undefined)));
      return true;
    }

    if (req.url === "/api/projects/mkdir" && req.method === "POST") {
      const body = await readBody(req);
      const data = JSON.parse(body || "{}") as {
        parent?: string;
        name?: string;
      };
      const result = createBrowseFolder(data.parent ?? "", data.name ?? "");
      res.end(JSON.stringify(result));
      return true;
    }

    if (req.url?.startsWith("/api/projects/inspect") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const dir = u.searchParams.get("dir") ?? "";
      res.end(JSON.stringify(inspectProjectDir(dir)));
      return true;
    }

    if (req.url === "/api/projects/default-root" && req.method === "GET") {
      res.end(
        JSON.stringify({
          path: getDefaultRoot(),
          browseStart: browseDirs().defaultRoot,
        })
      );
      return true;
    }

    // —— Data APIs (require open project) ——
    const root = requireRoot();

    if (req.url === "/api/preferences" && req.method === "GET") {
      res.end(JSON.stringify(loadPreferences(root)));
      return true;
    }

    if (req.url === "/api/preferences" && req.method === "PATCH") {
      const body = await readBody(req);
      const patch = JSON.parse(body || "{}");
      const prefs = savePreferences(root, patch);
      res.end(JSON.stringify(prefs));
      return true;
    }

    if (req.url === "/api/tasks" && req.method === "GET") {
      res.end(JSON.stringify(parseAllTasks(root)));
      return true;
    }

    if (req.url === "/api/overview" && req.method === "GET") {
      const tasks = parseAllTasks(root);
      res.end(JSON.stringify(getOverview(root, tasks)));
      return true;
    }

    if (req.url === "/api/analytics" && req.method === "GET") {
      res.end(JSON.stringify(getAnalyticsData(root)));
      return true;
    }

    if (req.url?.startsWith("/api/audit") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const action = u.searchParams.get("action") ?? undefined;
      const q = u.searchParams.get("q") ?? undefined;
      const split = (key: string) => {
        const raw = u.searchParams.get(key);
        if (!raw?.trim()) return undefined;
        const parts = raw
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean);
        return parts.length ? parts : undefined;
      };
      const tracker = split("tracker");
      const priority = split("priority");
      const tag = split("tag");
      const impact = split("impact");
      const effort = split("effort");
      const limitRaw = u.searchParams.get("limit");
      const limit = limitRaw ? Number(limitRaw) : undefined;
      res.end(
        JSON.stringify(
          listAudit(root, {
            action,
            q,
            tracker,
            priority,
            tag,
            impact,
            effort,
            limit:
              limit != null && Number.isFinite(limit)
                ? Math.min(Math.max(1, Math.floor(limit)), 2000)
                : undefined,
          })
        )
      );
      return true;
    }

    if (req.url === "/api/audit/clear" && req.method === "POST") {
      clearAudit(root);
      res.end(JSON.stringify({ ok: true }));
      return true;
    }

    if (req.url?.startsWith("/api/area/check") && req.method === "GET") {
      const u = new URL(req.url, "http://local");
      const name = u.searchParams.get("name") ?? "";
      res.end(JSON.stringify(checkAreaName(root, name)));
      return true;
    }

    if (req.url === "/api/task/toggle" && req.method === "POST") {
      const body = await readBody(req);
      const { id, completed } = JSON.parse(body);
      toggleTask(root, id, completed);
      res.end(JSON.stringify({ ok: true, tasks: parseAllTasks(root) }));
      return true;
    }

    if (req.url === "/api/task/move" && req.method === "POST") {
      const body = await readBody(req);
      const { id, priority, file } = JSON.parse(body);
      if (file) {
        moveTaskToFile(root, id, file);
      } else {
        moveTask(root, id, priority);
      }
      res.end(JSON.stringify({ ok: true, tasks: parseAllTasks(root) }));
      return true;
    }

    if (req.url === "/api/task/meta" && req.method === "POST") {
      const body = await readBody(req);
      const { key, tags, start, due, links, notes, impact, effort } =
        JSON.parse(body);
      if (!key) throw new Error("key required");
      const before = loadStore(root).byKey[key];
      const meta = updateTaskMeta(root, key, {
        tags,
        start,
        due,
        links,
        notes,
        impact,
        effort,
      });
      const changes = describeMetaChange(before, meta);
      if (changes.length) {
        appendAudit(
          root,
          "task.meta",
          `Updated #${meta.number}: ${changes.join("; ")}`,
          {
            key,
            number: meta.number,
            changes,
            meta,
            impact: meta.impact ?? null,
            effort: meta.effort ?? null,
          }
        );
      }
      res.end(
        JSON.stringify({
          ok: true,
          meta,
          tasks: parseAllTasks(root),
        })
      );
      return true;
    }

    if (req.url === "/api/task/create" && req.method === "POST") {
      const body = await readBody(req);
      const data = JSON.parse(body);
      const id = createTask(root, data);
      const tasks = parseAllTasks(root);
      res.end(JSON.stringify({ ok: true, id, tasks }));
      return true;
    }

    if (req.url === "/api/task/text" && req.method === "POST") {
      const body = await readBody(req);
      const { id, title, description } = JSON.parse(body);
      if (!id || !title?.trim()) throw new Error("id and title required");
      updateTaskText(root, id, { title, description });
      res.end(JSON.stringify({ ok: true, tasks: parseAllTasks(root) }));
      return true;
    }

    if (req.url === "/api/task/delete" && req.method === "POST") {
      const body = await readBody(req);
      const { id } = JSON.parse(body);
      if (!id) throw new Error("id required");
      deleteTask(root, id);
      res.end(JSON.stringify({ ok: true, tasks: parseAllTasks(root) }));
      return true;
    }

    if (req.url === "/api/area/create" && req.method === "POST") {
      const body = await readBody(req);
      const { name, title } = JSON.parse(body);
      const file = createArea(root, name, title);
      res.end(
        JSON.stringify({
          ok: true,
          file,
          tasks: parseAllTasks(root),
        })
      );
      return true;
    }

    if (req.url === "/api/tag/create" && req.method === "POST") {
      const body = await readBody(req);
      const { name } = JSON.parse(body);
      const tags = addGlobalTag(root, name);
      res.end(
        JSON.stringify({
          ok: true,
          tags,
          styles: getTagStyles(root),
        })
      );
      return true;
    }

    if (req.url === "/api/tags" && req.method === "GET") {
      res.end(
        JSON.stringify({
          tags: listAllTags(root),
          styles: getTagStyles(root),
          palette: tagPalette(),
        })
      );
      return true;
    }

    if (req.url === "/api/tag/rename" && req.method === "POST") {
      const body = await readBody(req);
      const { from, to } = JSON.parse(body);
      const result = renameGlobalTag(root, from, to);
      res.end(
        JSON.stringify({
          ok: true,
          ...result,
          tasks: parseAllTasks(root),
        })
      );
      return true;
    }

    if (req.url === "/api/tag/color" && req.method === "POST") {
      const body = await readBody(req);
      const { tag, style } = JSON.parse(body);
      const styles = setTagStyle(root, tag, style);
      res.end(JSON.stringify({ ok: true, styles }));
      return true;
    }

    if (req.url === "/api/tag/delete" && req.method === "POST") {
      const body = await readBody(req);
      const { tag, removeFromTasks } = JSON.parse(body);
      const result = deleteGlobalTag(root, tag, Boolean(removeFromTasks));
      res.end(
        JSON.stringify({
          ok: true,
          ...result,
          styles: getTagStyles(root),
          tasks: parseAllTasks(root),
        })
      );
      return true;
    }

    if (req.url === "/api/area/rename" && req.method === "POST") {
      const body = await readBody(req);
      const { file, name } = JSON.parse(body);
      const result = renameArea(root, file, name);
      res.end(
        JSON.stringify({
          ok: true,
          ...result,
          tasks: parseAllTasks(root),
        })
      );
      return true;
    }

    if (req.url === "/api/trackers/styles" && req.method === "GET") {
      res.end(JSON.stringify({ styles: getTrackerStyles(root) }));
      return true;
    }

    if (req.url === "/api/tracker/color" && req.method === "POST") {
      const body = await readBody(req);
      const { file, style } = JSON.parse(body);
      const styles = setTrackerStyle(root, file, style);
      res.end(JSON.stringify({ ok: true, styles }));
      return true;
    }

    res.statusCode = 404;
    res.end(JSON.stringify({ error: "Not found" }));
    return true;
  } catch (e) {
    const msg = String(e);
    res.statusCode = msg.includes("No project open") ? 401 : 500;
    res.end(JSON.stringify({ error: msg }));
    return true;
  }
}

import type { Task } from "./types";
import { prioritySlug, stripMd, isOverdue } from "./types";

/** All searchable text for a task, normalized to lowercase tokens. */
export function taskSearchIndex(t: Task): string[] {
  const plain = stripMd(t.text).toLowerCase();
  const title = (t.title || plain).toLowerCase();
  const fileBase = t.file.replace(/\.md$/i, "").replace(/\\/g, "/").toLowerCase();
  const parts = [
    String(t.number),
    `#${t.number}`,
    t.id.toLowerCase(),
    t.key.toLowerCase(),
    t.file.toLowerCase(),
    fileBase,
    t.fileTitle.toLowerCase(),
    t.area.toLowerCase(),
    t.area.replace(/-/g, " "),
    t.priority.toLowerCase(),
    prioritySlug(t.priority),
    title,
    plain,
    t.text.toLowerCase(),
    t.notes.toLowerCase(),
    t.start ?? "",
    t.due ?? "",
    t.start ? formatDateLabel(t.start) : "",
    t.due ? formatDateLabel(t.due) : "",
    ...t.tags,
    ...t.tags.map((tag) => `#${tag}`),
    ...t.links.map((n) => String(n)),
    ...t.links.map((n) => `#${n}`),
    t.completed ? "done complete completed closed" : "open active pending",
    isOverdue(t) ? "overdue late past-due" : "",
    `line ${t.line}`,
  ];

  return parts.filter(Boolean);
}

function formatDateLabel(iso: string): string {
  try {
    const d = new Date(iso + "T12:00:00");
    return d.toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    }).toLowerCase();
  } catch {
    return iso;
  }
}

export type ParsedQuery = {
  raw: string;
  freeText: string[];
  fields: Record<string, string[]>;
};

const FIELD_ALIASES: Record<string, string> = {
  tag: "tag",
  tags: "tag",
  label: "tag",
  labels: "tag",
  area: "tracker",
  file: "tracker",
  tracker: "tracker",
  priority: "priority",
  pri: "priority",
  p: "priority",
  due: "due",
  deadline: "due",
  start: "start",
  from: "start",
  note: "notes",
  notes: "notes",
  link: "link",
  links: "link",
  id: "id",
  num: "id",
  number: "id",
  status: "status",
  title: "title",
  text: "text",
  desc: "text",
  description: "text",
};

/** Parse `tag:gemini due:2026-07 overdue` style queries. */
export function parseSearchQuery(input: string): ParsedQuery {
  const raw = input.trim();
  const fields: Record<string, string[]> = {};
  const freeText: string[] = [];

  const re = /(?:^|\s)([a-z]+):("([^"]+)"|(\S+))/gi;
  let free = raw;
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw)) !== null) {
    const key = FIELD_ALIASES[m[1].toLowerCase()] ?? m[1].toLowerCase();
    const val = (m[3] ?? m[4] ?? "").toLowerCase();
    if (!fields[key]) fields[key] = [];
    fields[key].push(val);
    free = free.replace(m[0], " ");
  }

  const quoted = [...free.matchAll(/"([^"]+)"/g)].map((x) => x[1].toLowerCase());
  free = free.replace(/"([^"]+)"/g, " ");

  for (const token of free.toLowerCase().split(/\s+/)) {
    const t = token.replace(/^#/, "").trim();
    if (t) freeText.push(t);
  }

  return { raw, freeText: [...freeText, ...quoted], fields };
}

function fieldValue(t: Task, field: string): string {
  switch (field) {
    case "tag":
      return t.tags.join(" ");
    case "tracker":
      return `${t.area} ${t.file} ${t.fileTitle}`;
    case "priority":
      return `${t.priority} ${prioritySlug(t.priority)}`;
    case "due":
      return t.due ?? "";
    case "start":
      return t.start ?? "";
    case "notes":
      return t.notes;
    case "link":
      return t.links.map((n) => `#${n} ${n}`).join(" ");
    case "id":
      return `${t.number} #${t.number}`;
    case "status":
      return t.completed
        ? "done complete completed"
        : isOverdue(t)
          ? "open overdue"
          : "open active";
    case "title":
      return t.title || stripMd(t.text);
    case "text":
      return stripMd(t.text);
    default:
      return "";
  }
}

function matchesField(t: Task, field: string, values: string[]): boolean {
  const hay = fieldValue(t, field).toLowerCase();
  const extra =
    field === "due" || field === "start"
      ? [formatDateLabel(hay).toLowerCase()].filter(Boolean)
      : [];
  const blob = [hay, ...extra].join(" ");

  return values.every((v) => {
    if (field === "status") {
      if (v === "overdue") return isOverdue(t);
      if (v === "done" || v === "complete" || v === "completed")
        return t.completed;
      if (v === "open" || v === "active" || v === "pending")
        return !t.completed;
    }
    if (field === "id") {
      const n = v.replace(/^#/, "");
      return String(t.number) === n || hay.includes(n);
    }
    if (field === "tag") {
      return t.tags.some((tag) => tag.includes(v));
    }
    if (field === "link") {
      const n = parseInt(v.replace(/^#/, ""), 10);
      return Number.isFinite(n) && t.links.includes(n);
    }
    if (field === "priority") {
      return (
        t.priority.toLowerCase().includes(v) ||
        prioritySlug(t.priority).includes(v.replace(/\s+/g, "-"))
      );
    }
    return blob.includes(v);
  });
}

function matchesFreeText(t: Task, tokens: string[]): boolean {
  if (!tokens.length) return true;
  const index = taskSearchIndex(t).join(" ");
  return tokens.every((token) => {
    if (token === "overdue") return isOverdue(t);
    if (token === "done" || token === "complete" || token === "completed")
      return t.completed;
    if (token === "open" || token === "active" || token === "pending")
      return !t.completed;
    // bare number → issue id or link
    if (/^\d+$/.test(token)) {
      return (
        String(t.number) === token ||
        t.links.includes(parseInt(token, 10)) ||
        index.includes(token)
      );
    }
    return index.includes(token);
  });
}

export function taskMatchesSearch(t: Task, query: string): boolean {
  const trimmed = query.trim();
  if (!trimmed) return true;
  const parsed = parseSearchQuery(trimmed);

  for (const [field, values] of Object.entries(parsed.fields)) {
    if (!matchesField(t, field, values)) return false;
  }

  return matchesFreeText(t, parsed.freeText);
}

export function filterTasks(tasks: Task[], query: string): Task[] {
  const trimmed = query.trim();
  if (!trimmed) return tasks;
  return tasks.filter((t) => taskMatchesSearch(t, trimmed));
}

export function searchResultLabel(query: string, count: number, total: number): string {
  if (!query.trim()) return "";
  if (count === 0) return `no matches for “${query.trim()}”`;
  if (count === total) return `${count} match${count === 1 ? "" : "es"}`;
  return `${count} of ${total}`;
}

