function normalizeClientPrefs(data: Partial<Preferences> | null): Preferences {
  return {
    ...DEFAULT_PREFERENCES,
    ...data,
    theme: isThemeId(data?.theme) ? data.theme : DEFAULT_PREFERENCES.theme,
    language: isLanguageId(data?.language)
      ? data.language
      : DEFAULT_PREFERENCES.language,
    includeDone:
      typeof data?.includeDone === "boolean"
        ? data.includeDone
        : DEFAULT_PREFERENCES.includeDone,
    tipsMarqueeEnabled:
      typeof data?.tipsMarqueeEnabled === "boolean"
        ? data.tipsMarqueeEnabled
        : DEFAULT_PREFERENCES.tipsMarqueeEnabled,
    views: data?.views && typeof data.views === "object" ? data.views : {},
    filters:
      data?.filters && typeof data.filters === "object" ? data.filters : {},
  };
}
