export type AuditEntry = {
  id: string;
  at: string;
  action: string;
  summary: string;
  details?: Record<string, unknown>;
};

export async function fetchAudit(opts?: {
  action?: string;
  q?: string;
  tracker?: string | string[];
  priority?: string | string[];
  tag?: string | string[];
  impact?: string | string[];
  effort?: string | string[];
  limit?: number;
}): Promise<AuditEntry[]> {
  const u = new URL("/api/audit", window.location.origin);
  if (opts?.action) u.searchParams.set("action", opts.action);
  if (opts?.q) u.searchParams.set("q", opts.q);
  const trackers = Array.isArray(opts?.tracker)
    ? opts.tracker
    : opts?.tracker
      ? [opts.tracker]
      : [];
  const priorities = Array.isArray(opts?.priority)
    ? opts.priority
    : opts?.priority
      ? [opts.priority]
      : [];
  const tags = Array.isArray(opts?.tag)
    ? opts.tag
    : opts?.tag
      ? [opts.tag]
      : [];
  const impacts = Array.isArray(opts?.impact)
    ? opts.impact
    : opts?.impact
      ? [opts.impact]
      : [];
  const efforts = Array.isArray(opts?.effort)
    ? opts.effort
    : opts?.effort
      ? [opts.effort]
      : [];
  if (trackers.length) u.searchParams.set("tracker", trackers.join(","));
  if (priorities.length) u.searchParams.set("priority", priorities.join(","));
  if (tags.length) u.searchParams.set("tag", tags.join(","));
  if (impacts.length) u.searchParams.set("impact", impacts.join(","));
  if (efforts.length) u.searchParams.set("effort", efforts.join(","));
  if (opts?.limit != null) u.searchParams.set("limit", String(opts.limit));
  const r = await fetch(u.pathname + u.search);
  if (!r.ok) throw new Error("Failed to load audit");
  return r.json();
}

